INSERT INTO projects VALUES
    ('quack-query', 'Quack Query', 'Live', 'Latest · LLM + SQL in the browser', 2026, true, 'active', 'Ask a data file questions in plain English: an LLM writes one read-only SQL query and DuckDB runs it in your browser.', ['DuckDB-Wasm', 'SQL', 'LLM APIs'], [{'label': 'Open the live app', 'url': 'https://quack-query.vercel.app'}, {'label': 'GitHub', 'url': 'https://github.com/lmansf/Quack-Query'}], 1),
    ('fraud', 'Fraud Detection Pipeline', 'Running', 'Data engineering · Fraud analytics', 2026, true, 'active', 'Scores simulated webstore checkouts into Supabase. Its baseline rules flagged about half the fraud and no legitimate orders.', ['Databricks', 'Python', 'PostgreSQL (Supabase)', 'SQL'], [{'label': 'How the data flows', 'url': '/projects#fraud-flow'}, {'label': 'Live numbers', 'url': '/live'}, {'label': 'View on GitHub', 'url': 'https://github.com/lmansf/fraud-detection-pipeline/tree/claude/sweet-curie-3pzt7j'}], 2),
    ('owl-park', 'Owl Park', 'Live', 'Product analytics · Multiplayer web app', 2026, true, 'active', 'A live multiplayer owl park with Shopify tickets; every visit and sale lands in Supabase for analysis.', ['Cloudflare Workers', 'Shopify', 'PostgreSQL (Supabase)', 'SQL'], [{'label': 'Visit the park', 'url': 'https://exploreowlpark.com'}, {'label': 'How the data flows', 'url': '/projects#owl-park-flow'}, {'label': 'GitHub', 'url': 'https://github.com/lmansf/Welcome-to-Owl-Park'}], 3),
    ('lighthouse', 'Lighthouse', 'v0.15', 'Desktop app', 2026, false, 'active', 'A local-first desktop app that answers questions about a small group of files, with citations back to the passages it read. A Rust engine in a Tauri 2 shell handles extraction, on-device OCR and embeddings, and hybrid retrieval. A question over a spreadsheet becomes one read-only SQL query, run by DataFusion and shown verbatim. Use the bundled private model or bring your own key. Installers for Windows, macOS, and Linux.', ['Rust', 'Tauri 2', 'DataFusion', 'Next.js'], [{'label': 'lhvault.app', 'url': 'https://lhvault.app'}, {'label': 'GitHub', 'url': 'https://github.com/lmansf/lighthouse'}], 4),
    ('attendance', 'Attendance Forecasting', NULL, 'Forecasting · Machine learning', 2026, false, 'active', 'Daily theme-park attendance forecast from weather, calendar, and flight-traffic features. A blend of gradient-boosted trees, ridge, and random forest selected by rolling-origin cross-validation beat a tuned XGBoost by about 6% MAE out of fold and cut mean bias from +90 to −7 guests a day. The last 30 operating days are held out as an unseen live forecast with an 80% planning band from pooled out-of-fold ratios.', ['Python', 'XGBoost', 'scikit-learn'], [{'label': 'View on GitHub', 'url': 'https://github.com/lmansf/Attendance-Projections'}], 5),
    ('usl', 'USL Attendance Forecasting', NULL, 'Forecasting · Machine learning', 2026, false, 'active', 'An XGBoost demand model on nine seasons of USL Championship matches, on a staged DuckDB warehouse (raw → staging → marts). Two models share every upstream table and differ only by league-position features, so the error gap measures what promotion and relegation will do to attendance from 2028.', ['Python', 'XGBoost', 'DuckDB'], [{'label': 'View on GitHub', 'url': 'https://github.com/lmansf/USL-ticketing-and-stadium-revenue-forecasting'}], 6),
    ('roll-call', 'Roll Call', NULL, 'Data quality · Pipeline', 2026, false, 'active', 'A daily manatee-count pipeline for Blue Spring State Park, built around its data-quality layer: freshness, volume, distribution, and cross-source checks that quarantine suspect observations, open incidents, and email what newly broke. DuckDB on a systemd timer; an Evidence dashboard on Vercel.', ['Python', 'DuckDB', 'Evidence', 'Resend'], [{'label': 'View on GitHub', 'url': 'https://github.com/lmansf/Manatee-Role-Call'}], 7),
    ('nowcast', 'Attendance Nowcast', NULL, 'Learning project · Data assimilation', 2026, false, 'active', 'A Kalman-filter nowcast of daily theme-park attendance: predict from yesterday’s state, then correct with today’s partial signals, weighting each by its uncertainty. Written up as a five-notebook series from the scalar filter upward.', ['Python', 'Kalman filter', 'Notebooks'], [{'label': 'View on GitHub', 'url': 'https://github.com/lmansf/Attendance-Nowcast'}], 8),
    ('rfm', 'Member Segmentation (RFM)', NULL, 'Analytics · Power BI', 2025, false, 'active', 'Recency, frequency, and monetary segmentation of membership data, modeled in SQL and reported in Power BI, to turn one big member list into groups a marketing team can act on differently.', ['Power BI', 'SQL', 'Segmentation'], [{'label': 'View on GitHub', 'url': 'https://github.com/lmansf/Member-Segmentation-Analysis'}], 9),
    ('efrog', 'eFrog', 'Retired', 'Machine learning · Audio', 2026, false, 'archived', 'An audio-classification model that identified 19 Floridian frog species from a recording. The web app is retired; the model and code are still on GitHub.', ['Python', 'Audio ML'], [{'label': 'GitHub', 'url': 'https://github.com/lmansf/efrog'}], 10),
    ('owl-park-pipeline', 'Owl Park Data Architecture', 'Archived', 'End-to-end pipeline', 2025, false, 'archived', 'The first Owl Park: a simulated ticket-sales ecosystem where n8n agents role-played customers and managed stock, Supabase stored the orders, Microsoft Fabric modeled them medallion-style, and Power BI turned them into decisions. Retired, but the architecture diagram is still worth a look.', ['n8n', 'Supabase', 'Microsoft Fabric', 'Power BI'], [{'label': 'View the architecture diagram', 'url': '/owl-park'}], 11);

